order_profit = (
    df.groupby(["Customer_Segment", "invoice_id"])["Profit"].sum().reset_index()
)
avg_profit = order_profit.groupby("Customer_Segment")["Profit"].mean()
best_segment = avg_profit.idxmax()

result = {
    "avg_profit_per_order": avg_profit.round(2).to_dict(),
    "best_performing_segment": best_segment,
    "best_segment_avg_profit": round(avg_profit[best_segment], 2),
}

